#!/usr/bin/env python3
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
SITE=ROOT/'site'
BASE='/dc-public-realm'

home=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Diplomatic Gifts in Washington</title><link rel="stylesheet" href="{BASE}/assets/style.css"><style>.hero{{max-width:800px;margin:2rem 0}}.hero h1{{margin-bottom:.7rem}}.project{{border-left:4px solid #5a3d16;background:#fffdf8;padding:1rem 1.2rem;margin:2rem 0}}.project h2{{margin-top:.2rem}}.callout{{background:#f6f6f3;padding:1rem;margin:1.2rem 0}}.actions{{margin:1.2rem 0}}.actions .button{{margin-bottom:.5rem}}</style></head><body><header><div class="kicker">Diplomatic Gifts in Washington · research alpha</div><nav><a href="{BASE}/">Home</a><a href="{BASE}/objects/jose-gervasio-artigas/">Artigas</a><a href="{BASE}/collaborate/artigas/">Collaborate</a><a href="{BASE}/methodology/">Methodology</a></nav></header><main><section class="hero"><div class="kicker">PUBLIC ART · DIPLOMATIC HISTORY</div><h1>Diplomatic Gifts in Washington</h1><p class="lede">This research project documents diplomatic monuments in Washington, D.C., and the records associated with their creation, presentation, and installation.</p><p>Entries bring together information from government records, museum catalogs, archival sources, and published research. Where sources differ or information has not been established, the record identifies those questions for further research.</p></section><section class="project"><div class="kicker">CURRENT PROJECT · URUGUAY</div><h2>José Gervasio Artigas Memorial</h2><p>The memorial to José Gervasio Artigas stands in Washington, D.C. Records in the United States and Uruguay document its presentation and connect the bronze to an earlier monument in Uruguay. Published sources differ, however, in their descriptions of the earlier work and the Washington bronze's fabrication history.</p><div class="actions"><a class="button" href="{BASE}/objects/jose-gervasio-artigas/">View the Artigas record</a><a class="button" href="{BASE}/collaborate/artigas/">Research questions</a><a class="button" href="{BASE}/review/artigas/">Review the record</a></div></section><section><h2>About the project</h2><p>The project records individual historical and attribution claims with the sources that support, qualify, or contradict them. This makes it possible to distinguish information established by a source from information repeated from an earlier publication.</p><p>Research is ongoing. Records may be revised as additional documentation is located and reviewed.</p></section><section><h2>Current research</h2><p>For the Artigas memorial, current work concerns the sculpture's predecessor, casting history, and creative roles. The Smithsonian American Art Museum's Inventories of American Painting and Sculpture cites earlier research by George Washington University professor James M. Goode, the National Park Service, Michael Richman, and a 1991 Smithsonian research project. The public inventory does not identify which of these sources supports each individual statement in the record.</p><div class="callout"><strong>Research question:</strong> Which documentary sources support the principal historical and attribution statements associated with the Washington Artigas memorial?</div><p>Open research includes locating the relevant Goode pages, Richman's 1967–69 research, the cited 1985 National Park Service record, the 1991 Smithsonian research files, and related Uruguayan and diplomatic records.</p><a class="button" href="{BASE}/collaborate/artigas/">View research questions</a></section><section><h2>Other records</h2><div class="grid"><article class="card"><div class="kicker">ARGENTINA</div><h3><a href="{BASE}/objects/jose-de-san-martin/">José de San Martín</a></h3><p>Research record for the Washington monument to José de San Martín, including questions concerning attribution and object history.</p></article><article class="card"><div class="kicker">CUBA</div><h3><a href="{BASE}/objects/cuban-american-friendship-urn/">Cuban-American Friendship Urn</a></h3><p>Research record for the Cuban-American Friendship Urn and its diplomatic and documentary history.</p></article></div></section><section><h2>Using the records</h2><p>Entries distinguish documentary history, attribution, and interpretation. Evidence panels identify the records associated with each claim and note conflicting or unresolved information. Technical provenance is available for readers who wish to examine the underlying research structure.</p><p><a href="{BASE}/methodology/">Methodology</a> · <a href="https://github.com/danielastone/dc-public-realm">Research data and documentation</a></p></section></main><footer>Cataloging and research are ongoing. Records may be updated as additional sources are reviewed.</footer></body></html>'''

collab=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Artigas Memorial Research Questions</title><link rel="stylesheet" href="{BASE}/assets/style.css"><style>.ask{{border-left:4px solid #7a3e00;background:#fffdf8;padding:1rem;margin:1rem 0}}.small{{font-family:ui-sans-serif,system-ui,sans-serif;color:#666;font-size:.9rem}}</style></head><body><header><div class="kicker">Diplomatic Gifts in Washington · research</div><nav><a href="{BASE}/">Home</a><a href="{BASE}/objects/jose-gervasio-artigas/">Artigas record</a><a href="{BASE}/review/artigas/">Review</a></nav></header><main><div class="kicker">JOSÉ GERVASIO ARTIGAS MEMORIAL</div><h1>Research Questions</h1><p class="lede">Research on the Washington Artigas memorial is ongoing. The questions below identify records that may clarify the monument's fabrication history and the sources used in later institutional catalogs.</p><h2>Sources cited by the Smithsonian inventory</h2><p>The Smithsonian inventory cites several earlier research sources. Locating these materials may help establish which source supports particular statements about the monument.</p><article class="ask"><h3>Goode (1974), pp. 443–444</h3><p>Locate the Artigas entry and any citations, notes, or acknowledgments associated with it.</p><a class="button" href="https://github.com/danielastone/dc-public-realm/issues/19">Research task</a></article><article class="ask"><h3>Michael Richman, 1967–69</h3><p>Locate the collection, folder, finding aid, or research notes for the work cited in the Smithsonian inventory.</p><a class="button" href="https://github.com/danielastone/dc-public-realm/issues/20">Research task</a></article><article class="ask"><h3>National Park Service, 1985</h3><p>Identify the National Park Service record cited by the Smithsonian inventory and any references associated with it.</p><a class="button" href="https://github.com/danielastone/dc-public-realm/issues/21">Research task</a></article><article class="ask"><h3>Smithsonian research project, 1991</h3><p>Locate project documentation that identifies the records consulted or conclusions recorded during the 1991 research.</p><a class="button" href="https://github.com/danielastone/dc-public-realm/issues/22">Research task</a></article><h2>Additional documentary questions</h2><article class="ask"><h3>Uruguay, 1894–1896</h3><p>Locate the commission and contract records concerning Juan Luis Blanes, Juan Manuel Blanes, and Dante Costa that underlie later descriptions of the San José monument.</p><p class="small">Useful documentation includes archival citations, catalog records, digital images, or authoritative reproductions.</p></article><article class="ask"><h3>Uruguay and the United States, approximately 1947–1951</h3><p>Locate diplomatic, fabrication, shipping, dedication, or installation records concerning the Washington bronze.</p></article><h2>Contributing information</h2><p>Corrections, archival citations, finding-aid references, scans, and information about related collections are welcome. New information is reviewed against the underlying source before the public record is changed. Conflicting evidence is retained when the available documentation does not support a single conclusion.</p><p><a class="button" href="{BASE}/objects/jose-gervasio-artigas/">View the Artigas record</a><a class="button" href="{BASE}/review/artigas/">Review summary</a></p></main><footer>Research is ongoing. Records may be revised as additional documentation is located and reviewed.</footer></body></html>'''

(SITE/'index.html').write_text(home,encoding='utf-8')
d=SITE/'collaborate'/'artigas'; d.mkdir(parents=True,exist_ok=True); (d/'index.html').write_text(collab,encoding='utf-8')
print('Updated project front door and Artigas collaboration page')
